mapper.select:
	/*common.coco.getCategoryComText*/

        SELECT DECODE(A.BYCA_COMORG_CODE,#{st_buyer}, A.COM_NAME_LOC, 
			        				(	SELECT B.COMORG_NAME 
			        					FROM BYCAORGL B 
			        					WHERE B.COMORG_CODE = (	SELECT BYCA_COMORG_CODE 
			        																FROM ICOMCMPY WHERE COM_CODE = #{st_buyer}	)
			        				)
			        			) AS ROOT_CATEGORY_NAME
		FROM ICOMCMPY A
		WHERE A.COM_CODE = #{st_buyer}
